    s3Title: 'Κοινοποίηση Δεδομένων',
    s3Body: 'Δεν πουλάμε ποτέ τα δεδομένα σου. Μοιραζόμαστε δεδομένα μόνο με:\n• Παρόχους υπηρεσιών (μόνο τα απαραίτητα για το ραντεβού)\n• Νομικές αρχές αν απαιτηθεί\n• Τεχνικούς συνεργάτες (hosting, payment) με αυστηρές συμβάσεις',
