    s4Body: 'Έχεις δικαίωμα:\n• Πρόσβασης στα δεδομένα σου\n• Διόρθωσης ανακριβών δεδομένων\n• Διαγραφής ("δικαίωμα στη λήθη")\n• Φορητότητας δεδομένων\n• Εναντίωσης στην επεξεργασία\n• Καταγγελίας στην Αρχή Προστασίας Δεδομένων',
