    s7Title: 'Διατήρηση Δεδομένων',
    s7Body: 'Διατηρούμε τα δεδομένα σου όσο διαρκεί ο λογαριασμός σου. Μετά τη διαγραφή, τα δεδομένα διαγράφονται εντός 30 ημερών, εκτός αν απαιτείται διατήρηση για νομικούς λόγους (π.χ. φορολογικοί έλεγχοι).',
