  faq: {
    title: 'Preguntas Frecuentes',
    subtitle: 'Las preguntas más comunes de nuestros usuarios',
    q1: '¿Qué es GlobiPet?',
    a1: 'GlobiPet es una super-app integrada para mascotas que combina servicios veterinarios, telemedicina, marketplace de productos, herramientas de salud con IA y comunidad de dueños en una plataforma.',
    q2: '¿Cómo creo una cuenta?',
    a2: 'Pulsa "Registrarse" arriba a la derecha, completa email, nombre y contraseña. También puedes iniciar sesión con Google. El registro es gratis.',
    q3: '¿Es gratis usar GlobiPet?',
    a3: 'Sí, el uso básico es completamente gratis. Solo pagas por servicios que reservas (vet, grooming) o productos del marketplace.',
    q4: '¿Cómo reservo cita con veterinario?',
    a4: 'Ve a Servicios → selecciona Veterinario → ve proveedores cerca → elige hora → confirma. Recibes confirmación instantánea y recordatorio antes.',
    q5: '¿Qué es la telemedicina?',
    a5: 'La telemedicina te permite conectar con un veterinario por videollamada sin salir de casa. Ideal para consultas, seguimientos y casos no urgentes.',
    q6: '¿Cómo funciona AI Health Check?',
    a6: 'Subes una foto de tu mascota (piel, ojos, oídos, heces) y la IA analiza problemas de salud potenciales. No reemplaza al veterinario pero ayuda en detección temprana.',
    q7: '¿Puedo cancelar citas?',
    a7: 'Sí. La cancelación es gratuita hasta 24 horas antes de la cita, con reembolso completo. Si cancelas dentro de las 24 horas, se reembolsa el 50% del importe. Si cancela el proveedor, siempre recuperas el importe completo.',
    q8: '¿Cómo me hago proveedor de servicios?',
    a8: 'Regístrate como "Proveedor", completa datos del negocio, sube licencias/certificaciones. Tras revisión (1-3 días) se activa tu perfil.',
    q9: '¿Cómo se protegen mis datos?',
    a9: 'La conexión con la plataforma siempre está cifrada (HTTPS), los datos sensibles como el teléfono se guardan cifrados y los datos se alojan en servidores en Europa. Cumplimos el RGPD. Consulta la Política de Privacidad para más detalles.',
    q10: '¿En qué países opera GlobiPet?',
    a10: 'Inicialmente disponible en Grecia y Chipre. En 2027 nos expandimos a España y Reino Unido.',
  },
