    updatedDate: '1 de Enero, 2026',
    intro: 'Bienvenido a GlobiPet. A continuación los términos y condiciones de uso de nuestra plataforma. Al registrarte y usar GlobiPet, aceptas estos términos.',
    s1Title: 'Aceptación de Términos',
    s1Body: 'Al acceder y usar los servicios de GlobiPet, aceptas incondicionalmente todos estos términos. Si no estás de acuerdo, por favor no uses la plataforma.',
    s2Title: 'Descripción del Servicio',
    s2Body: 'GlobiPet proporciona una plataforma digital que conecta dueños de mascotas con proveedores (veterinarios, peluqueros, entrenadores, etc.), telemedicina, herramientas IA, tienda online y comunidad.',
    s3Title: 'Creación de Cuenta',
    s3Body: 'Para usar nuestros servicios debes crear una cuenta con información precisa y actualizada. Eres responsable de la seguridad de tu contraseña y todas las acciones desde tu cuenta.',
    s4Title: 'Obligaciones del Usuario',
    s4Body: 'Los usuarios deben:\n• Proporcionar información precisa\n• No usar la plataforma para actividades ilegales\n• Respetar derechos de otros usuarios y proveedores\n• No compartir su cuenta',
    s5Title: 'Pagos y Reembolsos',
    s5Body: 'Los pagos se realizan vía pasarela segura. Las cancelaciones son gratis hasta 24 horas antes. Devoluciones de productos en 14 días desde recepción según legislación.',
    s6Title: 'Proveedores de Servicios',
    s6Body: 'GlobiPet actúa como plataforma intermediaria. Los proveedores son profesionales independientes únicos responsables de los servicios. GlobiPet no es responsable de decisiones médicas.',
    s7Title: 'Propiedad Intelectual',
    s7Body: 'Todo el contenido de la plataforma (textos, imágenes, logos, software) pertenece a GlobiPet o sus titulares. Reproducción sin permiso escrito está prohibida.',
    s8Title: 'Limitación de Responsabilidad',
    s8Body: 'GlobiPet se proporciona "tal cual". No garantizamos operación ininterrumpida o sin errores. Nuestra responsabilidad se limita al máximo permitido por ley.',
    s9Title: 'Modificación de Términos',
